<?php
require dirname(__DIR__).'/app/auth.php';
$error='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
 $email=trim((string)($_POST['email']??''));
 $account=query('SELECT * FROM eval_users WHERE email=? AND active=1',[$email])->fetch();
 if (!validToken()) $error='La sesión del formulario venció. Recarga e inténtalo de nuevo.';
 elseif (!$account || !password_verify((string)($_POST['password']??''),$account['password_hash'])) $error='El correo o la contraseña no son correctos.';
 else { session_regenerate_id(true); $_SESSION['user_id']=(int)$account['id']; unset($_SESSION['user']); header('Location: ./'); exit; }
}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Iniciar sesión · EVAL-NSM</title><link rel="stylesheet" href="assets/style.css"><link rel="stylesheet" href="assets/institucion.css?v=3"><link rel="stylesheet" href="assets/roles.css"></head><body class="login-body"><main class="login-layout"><section class="login-story"><div class="login-brand"><img class="crest" src="assets/escudo-mercedes.png" alt="Escudo institucional"><div><strong>EVAL-NSM</strong><p>Nuestra Señora de las Mercedes · Ayacucho</p></div></div><div class="eyebrow">APRENDEMOS JUNTAS</div><h1>Un espacio para aprender.<br>Un futuro por descubrir.</h1><img class="login-picture" src="assets/estudiantes-hero.png" alt="Estudiantes aprendiendo juntas"><p>Tu aula, tus actividades y tus recursos, en un solo lugar.</p></section><section class="login-form"><span class="eyebrow">BIENVENIDA A TU AULA</span><h2>Inicia sesión</h2><p>Ingresa con tu cuenta para acceder a tu espacio.</p><?php if($error): ?><div class="alert" role="alert"><?= escape($error) ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= escape($_SESSION['csrf']) ?>"><label for="email">Correo electrónico</label><input id="email" type="email" name="email" required autocomplete="username" placeholder="tu.correo@institucion.edu.pe" value="<?= escape($_POST['email']??'') ?>"><label for="password">Contraseña</label><input id="password" type="password" name="password" required autocomplete="current-password" placeholder="Escribe tu contraseña"><button class="button login-submit">Ingresar a EVAL-NSM →</button></form><div class="demo-accounts"><strong>Explora los perfiles de demostración</strong><p>Selecciona una cuenta. Contraseña común: <code>Mercedes2026!</code></p><div class="account-grid"><?php foreach($accounts as $key=>$account): ?><button type="button" class="account-choice" data-email="<?= escape($account['email']) ?>"><strong><?= escape($account['label']) ?></strong><small><?= escape($account['email']) ?></small></button><?php endforeach; ?></div><small>Cuentas de prueba conectadas: actividades, entregas y notas se comparten entre perfiles.</small></div></section></main><script>document.querySelectorAll('[data-email]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#email').value=button.dataset.email;document.querySelector('#password').value='Mercedes2026!';document.querySelector('#email').focus();}));</script></body></html>


